ALTER POLICY "auth read templates" ON public.audit_templates USING(published_at IS NOT NULL OR public.is_assurance_staff(auth.uid()));
ALTER POLICY "auth read template items" ON public.audit_template_items USING(EXISTS(SELECT 1 FROM public.audit_templates t WHERE t.id=template_id AND (t.published_at IS NOT NULL OR public.is_assurance_staff(auth.uid()))));
CREATE OR REPLACE FUNCTION public.guard_phase2_response() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.audits; i public.audit_template_items; BEGIN SELECT * INTO a FROM public.audits WHERE id=NEW.audit_id; SELECT * INTO i FROM public.audit_template_items WHERE id=NEW.template_item_id; IF i.template_id IS DISTINCT FROM a.template_id OR a.status NOT IN ('scheduled','in_progress') OR a.auditor_id IS DISTINCT FROM auth.uid() OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN RAISE EXCEPTION 'Only assigned MFA auditors may capture this checklist'; END IF; NEW.created_by=auth.uid(); NEW.review_status='pending'; IF EXISTS(SELECT 1 FROM unnest(NEW.evidence_ids) e WHERE NOT EXISTS(SELECT 1 FROM public.evidence_documents d WHERE d.id=e AND d.listing_id=a.listing_id)) THEN RAISE EXCEPTION 'Evidence must belong to this residence'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase2_response_guard BEFORE INSERT OR UPDATE ON public.audit_responses FOR EACH ROW EXECUTE FUNCTION public.guard_phase2_response();
CREATE OR REPLACE FUNCTION public.decide_corrective_action(_action uuid,_close boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.corrective_actions; BEGIN SELECT * INTO c FROM public.corrective_actions WHERE id=_action; IF c.id IS NULL OR NOT public.is_assurance_staff(auth.uid()) OR public.owns_listing(c.listing_id,auth.uid()) OR length(trim(_reason)) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Independent MFA reviewer and reason required'; END IF; IF _close AND NOT EXISTS(SELECT 1 FROM public.corrective_action_events e CROSS JOIN LATERAL unnest(e.evidence_ids) eid JOIN public.evidence_documents d ON d.id=eid WHERE e.action_id=_action AND d.scan_status='clean' AND d.review_status='approved') THEN RAISE EXCEPTION 'Checked proof of remedy required before closure'; END IF; UPDATE public.corrective_actions SET status=CASE WHEN _close THEN 'closed' ELSE 'open' END,verified_closed_at=CASE WHEN _close THEN now() ELSE NULL END,closure_reviewer_id=auth.uid(),reopen_count=reopen_count+CASE WHEN _close THEN 0 ELSE 1 END,updated_at=now() WHERE id=_action; INSERT INTO public.corrective_action_events(action_id,event_type,note) VALUES(_action,CASE WHEN _close THEN 'closed' ELSE 'reopened' END,_reason); END $$;
REVOKE ALL ON FUNCTION public.decide_corrective_action(uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.decide_corrective_action(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_phase2_template() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.audits WHERE template_id=OLD.id) THEN RAISE EXCEPTION 'Used checklists are immutable; create a new version'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase2_template_guard BEFORE UPDATE ON public.audit_templates FOR EACH ROW EXECUTE FUNCTION public.guard_phase2_template();